import os,re
mods={}
for dp,_,fns in os.walk('AlgebraicJacobian'):
    for fn in fns:
        if fn.endswith('.lean'):
            p=os.path.join(dp,fn); mods[p[:-5].replace('/','.')]=p
imp={}; own={}; bare=set()
for n,p in mods.items():
    ds=[]; o=False
    for line in open(p,errors='replace'):
        m=re.match(r'^import\s+([A-Za-z0-9_.]+)\s*$',line)
        if m:
            d=m.group(1)
            if d=='Mathlib': bare.add(n); o=True
            elif d.startswith('Mathlib.'): o=True
            elif d.startswith('AlgebraicJacobian'): ds.append(d)
    imp[n]=ds; own[n]=o
memo={}
def hasbare(m):
    if m in memo: return memo[m]
    memo[m]=False
    r = m in bare or any(hasbare(d) for d in imp.get(m,[]))
    memo[m]=r; return r
# at risk: no Mathlib import of its own, and nothing bare left in its closure
for m in sorted(mods):
    if not own[m] and not hasbare(m): print(mods[m])
PY
